function parseNotificationEvent(data) {
	try {
		const event = JSON.parse(data);
		if (event.type === "notification.created" && event.notification?.id) return event;
		if (event.type === "notifications.read" && event.readAt) return event;
	} catch {}
	return null;
}
function subscribeToActivityEvents(url, onActivity, onConnected, options = {}) {
	const { activityId, onNotification } = options;
	let socket;
	let retryTimer;
	let stopped = false;
	let retryMs = 500;
	const retry = () => {
		if (stopped || retryTimer) return;
		retryTimer = setTimeout(() => {
			retryTimer = void 0;
			connect();
		}, retryMs);
		retryMs = Math.min(retryMs * 2, 1e4);
	};
	const connect = async () => {
		try {
			const ticketResponse = await fetch("/api/v1/auth/activity-events-ticket", { method: "POST" });
			if (!ticketResponse.ok) throw new Error("Unable to authenticate activity events");
			const { token } = await ticketResponse.json();
			if (!token) throw new Error("Activity event ticket was missing");
			const socketUrl = new URL(url, window.location.href);
			if (window.location.protocol === "https:" && socketUrl.protocol === "ws:") {
				socketUrl.protocol = "wss:";
				if (socketUrl.hostname === window.location.hostname) socketUrl.port = "";
			}
			socketUrl.searchParams.set("ticket", token);
			if (stopped) return;
			socket = new WebSocket(socketUrl);
		} catch {
			retry();
			return;
		}
		socket.onopen = () => {
			retryMs = 500;
			if (activityId) socket?.send(JSON.stringify({
				type: "activity.subscribe",
				activityId
			}));
			onConnected();
		};
		socket.onmessage = ({ data }) => {
			const notificationEvent = parseNotificationEvent(String(data));
			if (notificationEvent) {
				onNotification?.(notificationEvent);
				return;
			}
			try {
				const event = JSON.parse(String(data));
				if ((event.type === "activity.created" || event.type === "activity.upload.skipped" || event.type === "activity.updated" || event.type === "activity.comment.created" || event.type === "activity.comment.updated" || event.type === "activity.comment.deleted" || event.type === "activity.like.updated" || event.type === "activity.best-efforts.available") && event.activity?.id) onActivity(event);
			} catch {}
		};
		socket.onclose = () => {
			retry();
		};
	};
	connect();
	return () => {
		stopped = true;
		clearTimeout(retryTimer);
		socket?.close();
	};
}
