import { r as apiUrl } from "../../../../chunks/api.js";
import { error } from "@sveltejs/kit";
//#region src/routes/live/[token]/+page.server.ts
var load = async ({ params, fetch }) => {
	const response = await fetch(apiUrl(`api/v1/live-workouts/shared/${params.token}`));
	if (!response.ok) throw error(response.status, "This live tracking link is unavailable.");
	return {
		workout: await response.json(),
		token: params.token
	};
};
//#endregion
export { load };
