var preferredLocale = () => {
	return "en";
};
function t(key, values = {}) {
	let value = catalogs[preferredLocale()][key];
	for (const [name, replacement] of Object.entries(values)) value = value.replaceAll(`{${name}}`, String(replacement));
	return value;
}
